from collections import deque

def transform(grid):
    """
    Fill maximal rectangular regions of uniform non-background color (>=4x4) with 4.
    Background color is 3 (gray).
    """
    rows, cols = len(grid), len(grid[0])
    background = 3

    processed = []
    rects_filled = 0

    for r in range(rows):
        for c in range(cols):
            # Skip if already processed or background
            if (r, c) in processed or grid[r][c] == background:
                continue

            color = grid[r][c]

            # Find maximal rectangle with this top-left corner
            # Expand right
            c_right = c
            while c_right + 1 < cols:
                if grid[r][c_right+1] == color or (r, c_right+1) in processed:
                    c_right += 1
                else:
                    break

            # Expand down
            r_bottom = r
            while r_bottom + 1 < rows:
                all_color = True
                for cc in range(c, c_right + 1):
                    if grid[r_bottom+1][cc] != color:
                        all_color = False
                        break
                if not all_color:
                    break
                r_bottom += 1

            h, w = r_bottom - r + 1, c_right - c + 1
            if h >= 4 and w >= 4:
                # Fill this rectangle with 4
                for rr in range(r, r_bottom + 1):
                    for cc in range(c, c_right + 1):
                        grid[rr][cc] = 4

                rects_filled += 1
                # Mark cells as processed
                for rr in range(r, r_bottom + 1):
                    for cc in range(c, c_right + 1):
                        processed.append((rr, cc))

    return grid

